import math


def cosine(a, b):
    if len(a) != len(b):
        raise ValueError('vectors must have the same length')
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    if na == 0 or nb == 0:
        return 0.0
    return round(sum(x * y for x, y in zip(a, b)) / (na * nb), 4) + 0.0

import math


def _score(q, d, metric):
    if metric == 'dot':
        return sum(x * y for x, y in zip(q, d))
    if metric == 'cosine':
        nq = math.sqrt(sum(x * x for x in q))
        nd = math.sqrt(sum(x * x for x in d))
        return 0.0 if nq == 0 or nd == 0 else sum(x * y for x, y in zip(q, d)) / (nq * nd)
    if metric == 'euclidean':
        return -math.sqrt(sum((x - y) ** 2 for x, y in zip(q, d)))
    raise ValueError(f'unknown metric {metric}')


def rank(query, docs, metric):
    scores = [_score(query, d, metric) for d in docs]
    return sorted(range(len(docs)), key=lambda i: (-scores[i], i))

