def knn(query, vectors, k):
    scored = [(i, round(_cos(query, v), 4) + 0.0) for i, v in enumerate(vectors)]
    scored.sort(key=lambda p: (-p[1], p[0]))
    return scored[:k]

def merge_results(shard_lists, k):
    best = {}
    for results in shard_lists:
        for doc, score in results:
            if doc not in best or score > best[doc]:
                best[doc] = score
    return sorted(best.items(), key=lambda p: (-p[1], p[0]))[:k]

def recall_at_k(retrieved, relevant, k):
    if not relevant:
        return 0.0
    return round(len(set(retrieved[:k]) & set(relevant)) / len(relevant), 4)


def precision_at_k(retrieved, relevant, k):
    if k == 0:
        return 0.0
    return round(len(set(retrieved[:k]) & set(relevant)) / k, 4)

def mrr(results):
    if not results:
        return 0.0
    total = 0.0
    for retrieved, relevant in results:
        for pos, doc in enumerate(retrieved, 1):
            if doc in relevant:
                total += 1 / pos
                break
    return round(total / len(results), 4)

import re


def build_index(docs):
    index = {}
    for i, text in enumerate(docs):
        for term in set(re.findall(r'[a-z0-9]+', text.lower())):
            index.setdefault(term, set()).add(i)
    return {t: sorted(ids) for t, ids in index.items()}


def and_query(index, terms):
    if not terms or any(t not in index for t in terms):
        return []
    result = set(index[terms[0]])
    for t in terms[1:]:
        result &= set(index[t])
    return sorted(result)

def rrf(rankings, k=60):
    scores = {}
    for lst in rankings:
        for rank, doc in enumerate(lst, 1):
            scores[doc] = scores.get(doc, 0.0) + 1 / (k + rank)
    return sorted(scores, key=lambda d: (-scores[d], d))

def _normalise(d):
    if not d:
        return {}
    lo, hi = min(d.values()), max(d.values())
    return {k: (1.0 if hi == lo else (v - lo) / (hi - lo)) for k, v in d.items()}


def weighted_fusion(dense, sparse, alpha):
    nd, ns = _normalise(dense), _normalise(sparse)
    docs = set(nd) | set(ns)
    scored = [(doc, round(alpha * nd.get(doc, 0.0) + (1 - alpha) * ns.get(doc, 0.0), 4) + 0.0) for doc in docs]
    return sorted(scored, key=lambda p: (-p[1], p[0]))

def chunk_words(text, size, overlap):
    if not 0 <= overlap < size:
        raise ValueError('need 0 <= overlap < size')
    words = text.split()
    chunks = []
    for start in range(0, len(words), size - overlap):
        chunks.append(' '.join(words[start:start + size]))
        if start + size >= len(words):
            break
    return chunks

