def filtered_search(query, items, where, k):
    matches = [it for it in items if all(it['meta'].get(key) == val for key, val in where.items())]
    matches.sort(key=lambda it: (-_cos(query, it['vector']), it['id']))
    return [it['id'] for it in matches[:k]]

def post_filter(ranked_ids, meta, where, k, fetch_k):
    ids = []
    for doc in ranked_ids[:fetch_k]:
        if all(meta[doc].get(key) == val for key, val in where.items()):
            ids.append(doc)
            if len(ids) == k:
                break
    return (ids, len(ids) == k)

def assign(points, centroids):
    def sq(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))
    return [min(range(len(centroids)), key=lambda c: (sq(p, centroids[c]), c)) for p in points]

def kmeans(points, k, iters):
    def sq(p, q):
        return sum((x - y) ** 2 for x, y in zip(p, q))

    def nearest(p, cents):
        return min(range(len(cents)), key=lambda c: (sq(p, cents[c]), c))

    cents = [list(map(float, p)) for p in points[:k]]
    for _ in range(iters):
        groups = [[] for _ in range(k)]
        for p in points:
            groups[nearest(p, cents)].append(p)
        cents = [[sum(col) / len(g) for col in zip(*g)] if g else cents[i] for i, g in enumerate(groups)]
    assignments = [nearest(p, cents) for p in points]
    return ([[round(x, 4) + 0.0 for x in c] for c in cents], assignments)

def ivf_build(vectors, centroids):
    def sq(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))
    lists = {c: [] for c in range(len(centroids))}
    for i, v in enumerate(vectors):
        c = min(range(len(centroids)), key=lambda j: (sq(v, centroids[j]), j))
        lists[c].append(i)
    return lists

def ivf_search(query, vectors, centroids, lists, nprobe, k):
    def sq(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))
    probe = sorted(range(len(centroids)), key=lambda c: (sq(query, centroids[c]), c))[:nprobe]
    candidates = [i for c in probe for i in lists[c]]
    return sorted(candidates, key=lambda i: (sq(query, vectors[i]), i))[:k]

def pq_encode(vector, codebooks):
    d = len(codebooks[0][0])
    if len(vector) != d * len(codebooks):
        raise ValueError('vector length does not match the codebooks')
    codes = []
    for j, book in enumerate(codebooks):
        part = vector[j * d:(j + 1) * d]
        codes.append(min(range(len(book)), key=lambda c: (sum((x - y) ** 2 for x, y in zip(part, book[c])), c)))
    return codes

def pq_distance(query, codes, codebooks):
    d = len(codebooks[0][0])
    total = 0.0
    for j, code in enumerate(codes):
        part = query[j * d:(j + 1) * d]
        total += sum((x - y) ** 2 for x, y in zip(part, codebooks[j][code]))
    return round(total, 4)


def pq_rank(query, all_codes, codebooks):
    dists = [pq_distance(query, c, codebooks) for c in all_codes]
    return sorted(range(len(all_codes)), key=lambda i: (dists[i], i))

def sq_fit(vectors):
    return ([min(col) for col in zip(*vectors)], [max(col) for col in zip(*vectors)])


def sq_encode(vector, mins, maxs):
    codes = []
    for x, lo, hi in zip(vector, mins, maxs):
        code = 0 if hi == lo else round((x - lo) / (hi - lo) * 255)
        codes.append(max(0, min(255, code)))
    return codes


def sq_decode(codes, mins, maxs):
    return [round(lo + c / 255 * (hi - lo), 4) + 0.0 for c, lo, hi in zip(codes, mins, maxs)]

def binarize(vector):
    code = 0
    for i, x in enumerate(vector):
        if x > 0:
            code |= 1 << i
    return code


def hamming(a, b):
    return bin(a ^ b).count('1')


def hamming_rank(query, codes):
    q = binarize(query)
    return sorted(range(len(codes)), key=lambda i: (hamming(q, codes[i]), i))

def _sig(v, planes):
    return ''.join('1' if sum(a * b for a, b in zip(v, p)) >= 0 else '0' for p in planes)


def lsh_candidates(query, vectors, tables):
    found = set()
    for planes in tables:
        q = _sig(query, planes)
        for i, v in enumerate(vectors):
            if _sig(v, planes) == q:
                found.add(i)
    return sorted(found)

def greedy_search(graph, vectors, query, entry):
    def d(n):
        return sum((x - y) ** 2 for x, y in zip(vectors[n], query))
    current, path = entry, [entry]
    while graph[current]:
        best = min(graph[current], key=lambda n: (d(n), n))
        if d(best) < d(current):
            current = best
            path.append(best)
        else:
            break
    return (current, path)

import heapq


def beam_search(graph, vectors, query, entry, ef, k):
    def d(n):
        return sum((x - y) ** 2 for x, y in zip(vectors[n], query))
    visited = {entry}
    candidates = [(d(entry), entry)]
    results = [(d(entry), entry)]
    while candidates:
        dist, node = heapq.heappop(candidates)
        if len(results) >= ef and dist > results[-1][0]:
            break
        for n in graph[node]:
            if n in visited:
                continue
            visited.add(n)
            dn = d(n)
            if len(results) < ef or dn < results[-1][0]:
                heapq.heappush(candidates, (dn, n))
                results.append((dn, n))
                results.sort()
                results = results[:ef]
    return [n for _, n in sorted(results)[:k]]

import math


def assign_levels(uniforms, M):
    if M < 2:
        raise ValueError('M must be at least 2')
    mL = 1 / math.log(M)
    levels = []
    for u in uniforms:
        if not 0 < u <= 1:
            raise ValueError('u must be in (0, 1]')
        levels.append(math.floor(-math.log(u) * mL) + 0)
    return levels

def select_neighbors(base, candidates, vectors, M):
    def d(a, b):
        return sum((x - y) ** 2 for x, y in zip(vectors[a], vectors[b]))
    kept = []
    for c in sorted(candidates, key=lambda c: (d(c, base), c)):
        if len(kept) == M:
            break
        if all(d(c, base) < d(c, s) for s in kept):
            kept.append(c)
    return kept

def pareto_front(configs):
    def dominated(c):
        return any(o['recall'] >= c['recall'] and o['latency_ms'] <= c['latency_ms']
                   and (o['recall'] > c['recall'] or o['latency_ms'] < c['latency_ms']) for o in configs)
    front = [c for c in configs if not dominated(c)]
    return [c['name'] for c in sorted(front, key=lambda c: (c['latency_ms'], c['name']))]

def pick_config(configs, min_recall, max_latency_ms=None):
    ok = [c for c in configs if c['recall'] >= min_recall and (max_latency_ms is None or c['latency_ms'] <= max_latency_ms)]
    if not ok:
        return None
    return min(ok, key=lambda c: (c['latency_ms'], -c['recall'], c['name']))['name']

