class VectorStore:
    def __init__(self):
        self.records = {}

    def upsert(self, id, vector, meta=None):
        version = self.records[id]['version'] + 1 if id in self.records else 1
        self.records[id] = {'vector': list(vector), 'meta': meta or {}, 'version': version, 'deleted': False}

    def delete(self, id):
        rec = self.records.get(id)
        if rec is None or rec['deleted']:
            return False
        rec['deleted'] = True
        return True

    def get(self, id):
        rec = self.records.get(id)
        if rec is None or rec['deleted']:
            return None
        return {'vector': rec['vector'], 'meta': rec['meta'], 'version': rec['version']}

    def count(self):
        return sum(1 for r in self.records.values() if not r['deleted'])

    def search(self, query, k):
        def cos(v):
            nq = math.sqrt(sum(x * x for x in query))
            nv = math.sqrt(sum(x * x for x in v))
            return 0.0 if nq == 0 or nv == 0 else sum(a * b for a, b in zip(query, v)) / (nq * nv)
        live = [(i, cos(r['vector'])) for i, r in self.records.items() if not r['deleted']]
        live.sort(key=lambda p: (-p[1], p[0]))
        return [i for i, _ in live[:k]]

def compact(records):
    latest = {}
    for r in records:
        if r['id'] not in latest or r['version'] > latest[r['id']]['version']:
            latest[r['id']] = r
    kept = sorted((i, r['version']) for i, r in latest.items() if not r['deleted'])
    return {'kept': kept, 'reclaimed': len(records) - len(kept)}

import hashlib


def shard_for(doc_id, shards):
    return int(hashlib.md5(doc_id.encode()).hexdigest(), 16) % shards


def shard_counts(doc_ids, shards):
    counts = [0] * shards
    for d in doc_ids:
        counts[shard_for(d, shards)] += 1
    return counts

