def mmr(query, docs, k, lam):
    selected = []
    remaining = sorted(docs)
    while remaining and len(selected) < k:
        def score(d):
            redundancy = max((_cos(docs[d], docs[s]) for s in selected), default=0.0)
            return lam * _cos(query, docs[d]) - (1 - lam) * redundancy
        best = min(remaining, key=lambda d: (-score(d), d))
        selected.append(best)
        remaining.remove(best)
    return selected

import re


def normalize_query(text, stopwords, spelling):
    tokens = [spelling.get(t, t) for t in re.findall(r'[a-z0-9]+', text.lower())]
    return ' '.join(t for t in tokens if t not in stopwords)

def expand_query(tokens, synonyms, max_variants):
    variants = [' '.join(tokens)]
    seen = set(variants)
    for i, t in enumerate(tokens):
        for s in synonyms.get(t, []):
            q = ' '.join(tokens[:i] + [s] + tokens[i + 1:])
            if q not in seen:
                seen.add(q)
                variants.append(q)
    return variants[:max_variants]

def assemble_context(chunks, budget):
    ids, used = [], 0
    for c in chunks:
        if used + c['tokens'] <= budget:
            ids.append(c['id'])
            used += c['tokens']
    return (ids, used)

def cite(sentences):
    numbers = {}
    parts = []
    for text, src in sentences:
        if src is None:
            parts.append(text)
        else:
            n = numbers.setdefault(src, len(numbers) + 1)
            parts.append(f'{text} [{n}]')
    return (' '.join(parts), list(numbers))

