class SemanticCache:
    def __init__(self, threshold):
        self.threshold = threshold
        self.entries = []
        self.hits = 0
        self.misses = 0

    def put(self, vector, answer):
        self.entries.append((list(vector), answer))

    def get(self, vector):
        def cos(a, b):
            na = math.sqrt(sum(x * x for x in a))
            nb = math.sqrt(sum(x * x for x in b))
            return 0.0 if na == 0 or nb == 0 else sum(x * y for x, y in zip(a, b)) / (na * nb)
        best, best_score = None, -2.0
        for v, answer in self.entries:
            s = cos(vector, v)
            if s > best_score:
                best, best_score = answer, s
        if best is not None and best_score >= self.threshold:
            self.hits += 1
            return best
        self.misses += 1
        return None

def cache_savings(events, llm_cost, lookup_cost):
    n = len(events)
    if n == 0:
        return {'hit_rate': 0.0, 'cost_without_cache': 0.0, 'cost_with_cache': 0.0, 'saved': 0.0}
    hits = events.count('hit')
    without = n * llm_cost
    with_cache = n * lookup_cost + (n - hits) * llm_cost
    return {'hit_rate': round(hits / n, 3), 'cost_without_cache': round(without, 2),
            'cost_with_cache': round(with_cache, 2), 'saved': round(without - with_cache, 2)}

