import math


def ndcg_at_k(grades, k):
    def dcg(g):
        return sum((2 ** x - 1) / math.log2(i + 2) for i, x in enumerate(g[:k]))
    ideal = dcg(sorted(grades, reverse=True))
    return round(dcg(grades) / ideal, 4) if ideal else 0.0

def evaluate(golden, results, k):
    recalls, rrs = {}, []
    for q in sorted(golden):
        ranked = results.get(q, [])
        rel = golden[q]
        recalls[q] = len(set(ranked[:k]) & rel) / len(rel) if rel else 0.0
        rr = 0.0
        for pos, doc in enumerate(ranked, 1):
            if doc in rel:
                rr = 1 / pos
                break
        rrs.append(rr)
    worst = min(sorted(recalls), key=lambda q: recalls[q])
    return {'recall_at_k': round(sum(recalls.values()) / len(recalls), 4), 'mrr': round(sum(rrs) / len(rrs), 4),
            'worst_query': worst}

