import math


def drift(baseline, current, threshold):
    def mean(vs):
        return [sum(col) / len(vs) for col in zip(*vs)]
    a, b = mean(baseline), mean(current)
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    cos = 0.0 if na == 0 or nb == 0 else sum(x * y for x, y in zip(a, b)) / (na * nb)
    d = round(1 - cos, 4) + 0.0
    return {'drift': d, 'alert': d > threshold}

def choose_format(n, dims, budget_gb, graph_m=16):
    mem = None
    for name, b in [('float32', 4), ('float16', 2), ('int8', 1), ('binary', 0.125)]:
        mem = round((n * dims * b + n * graph_m * 2 * 4) / 1e9, 2)
        if mem <= budget_gb:
            return (name, mem)
    return (None, mem)

import re


def redact(text):
    text, emails = re.subn(r'[\w.+-]+@[\w-]+\.[\w.]+', '[EMAIL]', text)
    text, phones = re.subn(r'\+?\d[\d -]{8,}\d', '[PHONE]', text)
    return (text, {'email': emails, 'phone': phones})

def forget_user(records, cache, user_id):
    rest = [r for r in records if r['owner'] != user_id]
    deleted = sorted(r['id'] for r in records if r['owner'] == user_id)
    rest_cache = {k: v for k, v in cache.items() if v['owner'] != user_id}
    audit = {'user': user_id, 'records_deleted': deleted, 'cache_deleted': len(cache) - len(rest_cache)}
    return (rest, rest_cache, audit)

import math


def hybrid_search(query_tokens, query_vec, docs, where, k, alpha):
    q = set(query_tokens)

    def cos(a, b):
        na = math.sqrt(sum(x * x for x in a))
        nb = math.sqrt(sum(x * x for x in b))
        return 0.0 if na == 0 or nb == 0 else sum(x * y for x, y in zip(a, b)) / (na * nb)

    scored = []
    for d in docs:
        if all(d['meta'].get(key) == val for key, val in where.items()):
            overlap = len(q & set(d['tokens'])) / len(q) if q else 0.0
            scored.append((d['id'], round(alpha * cos(query_vec, d['vector']) + (1 - alpha) * overlap, 4)))
    return sorted(scored, key=lambda p: (-p[1], p[0]))[:k]

def eval_report(runs, golden, k):
    if not golden:
        return {'queries': 0, 'recall_at_k': 0.0, 'mrr': 0.0, 'failed': []}
    recalls, rrs, failed = [], [], []
    for q in sorted(golden):
        ranked, rel = runs.get(q, []), golden[q]
        r = len(set(ranked[:k]) & rel) / len(rel) if rel else 0.0
        recalls.append(r)
        if r == 0:
            failed.append(q)
        rr = 0.0
        for pos, doc in enumerate(ranked, 1):
            if doc in rel:
                rr = 1 / pos
                break
        rrs.append(rr)
    n = len(golden)
    return {'queries': n, 'recall_at_k': round(sum(recalls) / n, 4), 'mrr': round(sum(rrs) / n, 4), 'failed': failed}
